import type { Component } from 'svelte';
/** A lazily imported Svelte component module. */
export type ComponentLoader = () => Promise<{
    default: Component<any>;
}>;
export interface LayoutEntry {
    dir: string;
    component: ComponentLoader | null;
    hasLoad: boolean;
}
export interface ErrorEntry {
    /** How many of the route's layouts wrap this error page. */
    layouts: number;
    component: ComponentLoader;
}
export interface RouteEntry {
    layouts: number[];
    page: ComponentLoader;
    hasLoad: boolean;
    errors: ErrorEntry[];
}
/** The client manifest generated by `tern gen` in .tern/generated/manifest.js. */
export interface ClientManifest {
    layouts: LayoutEntry[];
    routes: Record<string, RouteEntry>;
    fallback: {
        layouts: number[];
        errors: ErrorEntry[];
    };
}
/** What the server sends for a page, inline or from __data.json. */
export interface Payload {
    type: 'data' | 'error' | 'redirect' | 'success' | 'failure';
    route?: string;
    params?: Record<string, string>;
    status: number;
    nodes?: (Record<string, unknown> | null)[];
    failed?: number;
    error?: {
        message: string;
    };
    location?: string;
    data?: unknown;
    form?: unknown;
    hasForm?: boolean;
}
/** The result of submitting a form action with `use:enhance`. */
export type ActionResult<Success = Record<string, unknown>, Failure = Record<string, unknown>> = {
    type: 'success';
    status: number;
    data?: Success;
} | {
    type: 'failure';
    status: number;
    data?: Failure;
} | {
    type: 'redirect';
    status: number;
    location: string;
} | {
    type: 'error';
    status: number;
    error: {
        message: string;
    };
};
export interface NavigationTarget {
    url: URL;
    params: Record<string, string> | null;
    route: {
        id: string | null;
    };
}
export type NavigationType = 'enter' | 'link' | 'goto' | 'popstate' | 'form';
export interface Navigation {
    from: NavigationTarget | null;
    to: NavigationTarget | null;
    type: NavigationType;
}
export interface GotoOptions {
    /** Replace the current history entry instead of adding one. */
    replaceState?: boolean;
    /** Keep the scroll position instead of scrolling to the top. */
    noScroll?: boolean;
    /** Keep focus on the currently focused element. */
    keepFocus?: boolean;
    /** Rerun every load, even for the current URL. */
    invalidateAll?: boolean;
    /** State to store in the history entry, available as page.state. */
    state?: Record<string, unknown>;
}
